/* v2：登录页验证码提示合并为一条。
   幂等：可重复执行；不改动提示条的显示/隐藏逻辑，只统一文案。
   兼容 v5.6 / v5.7（两条旧文案都认），未来版本源码自带新文案时不会误改。 */
(function (w, d) {
  var TIP = "请再次点击验证码以更新，若仍未显示，则可能是服务器在23:00至6:00间夜间维护或仅允许校园网访问";
  var OLD_FAIL = "验证码没加载出来，点图片重试；仍不行请连校园网";
  var OLD_NIGHT = "教务系统夜间（23:00–06:00）常处于维护，且仅校园网可访问";
  function paint() {
    try {
      var t = d.getElementById("net-tip-txt");
      if (!t) return;
      var s = t.textContent;
      if (s !== TIP && (s === OLD_FAIL || s === OLD_NIGHT || !s)) t.textContent = TIP;
    } catch (e) {}
  }
  paint();                                   /* 首帧默认文案、以及已经渲染出来的提示，立即统一 */
  var el = d.getElementById("net-tip-txt");
  if (el && w.MutationObserver) {            /* 之后 netTip() 每次重设旧文案时自动纠正 */
    try { new MutationObserver(paint).observe(el, { childList: true, characterData: true, subtree: true }); }
    catch (e) {}
  }
})(window, document);

/* v5：下载入口改指 GitHub Release 上的 v5.20 安装包（123 云盘那份留在 README 备查）。
   仍然只接管两个「去下载」入口：强制升级遮罩 #zk-upgrade、设置页「检查新版本」#btn-check-update。
   打开方式优先原生 openUrl（只拉起系统浏览器，不写剪贴板、不弹「下载密码」，因为 GitHub 不需要密码），
   老桥没有 openUrl 才退回 openDownloadPage，再不行才 window.open。 */
(function (w, d) { 
  var URL = "https://github.com/PWHbut/zk-guard/releases/download/v5.20/zhike-5.20.apk";
  var TIP = "已打开 GitHub 下载页 · 下完点通知安装";
  function open(N) {
    if (N && typeof N.openUrl === "function") {
      try { N.openUrl(URL); } catch (e) {}
      try { if (typeof N.toast === "function") N.toast(TIP); } catch (e) {}
      return true;
    }
    if (N && typeof N.openDownloadPage === "function") {
      try { N.openDownloadPage(URL, ""); return true; } catch (e) {}
    }
    return false;
  }
  d.addEventListener("click", function (e) {
    var t = e.target;
    var hit = t && t.closest && t.closest("#zk-upgrade, #btn-check-update, [data-zk='check-update']");
    if (!hit) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    if (open(w.ZhikeNative)) return;
    try { w.open(URL, "_blank", "noopener,noreferrer"); } catch (e) {}
  }, true);
})(window, document);
